// Plan de la VPC 10.50.0.0/16: una pública, dos subredes de gestión y una de datos.
export const plan = {
  vpc: "10.50.0.0/16",
  subnets: [
    { name: "publica-a", cidr: "10.50.0.0/24" },
    { name: "gestion-a", cidr: "10.50.1.0/27" },
    { name: "gestion-b", cidr: "10.50.1.32/27" },
    { name: "datos-a", cidr: "10.50.2.0/24" },
  ],
};

spec.code:
const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["gestion-a", "gestion-b"]) {
  const hay = aws.cidr.usableAddresses(sub(name).cidr);
  assert.ok(hay >= 20, name + " ofrece " + hay + " direcciones utilizables y se piden 20");
}

const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
assert.strictEqual(plan.subnets.length, 4);
assert.strictEqual(sub("publica-a").cidr, "10.50.0.0/24");
assert.strictEqual(sub("datos-a").cidr, "10.50.2.0/24");

const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["gestion-a", "gestion-b"]) {
  assert.ok(aws.cidr.usableAddresses(sub(name).cidr) <= 27, name + " es más grande de lo necesario");
}

const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
assert.strictEqual(aws.cidr.parse(sub("gestion-a").cidr)?.network, "10.50.1.0");
assert.strictEqual(aws.cidr.parse(sub("gestion-b").cidr)?.network, "10.50.1.32");

assert.strictEqual(plan.vpc, "10.50.0.0/16");
const subnets: { name: string; cidr: string }[] = plan.subnets;
for (const [index, first] of subnets.entries()) {
  assert.ok(aws.cidr.contains(plan.vpc, first.cidr), first.name + " queda fuera de la VPC");
  for (const second of subnets.slice(index + 1)) {
    assert.ok(!aws.cidr.overlaps(first.cidr, second.cidr), first.name + " se solapa con " + second.name);
  }
}

