// Plan de la VPC de la tienda: un /16 privado sin chocar con 172.17.0.0/16 y subredes con el tamaño justo.
export const plan = {
  vpc: "10.30.0.0/16",
  subnets: [
    { name: "publica-a", cidr: "10.30.0.0/25" },
    { name: "publica-b", cidr: "10.30.0.128/25" },
    { name: "privada-a", cidr: "10.30.8.0/21" },
    { name: "privada-b", cidr: "10.30.16.0/21" },
  ],
};

spec.code:
const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["publica-a", "publica-b"]) {
  const hay = aws.cidr.usableAddresses(sub(name).cidr);
  assert.ok(hay >= 120, name + " ofrece " + hay + " direcciones utilizables y se piden 120");
}
for (const name of ["privada-a", "privada-b"]) {
  const hay = aws.cidr.usableAddresses(sub(name).cidr);
  assert.ok(hay >= 2000, name + " ofrece " + hay + " direcciones utilizables y se piden 2000");
}

const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["publica-a", "publica-b"]) {
  assert.ok(aws.cidr.usableAddresses(sub(name).cidr) <= 123, name + " es más grande de lo necesario");
}
for (const name of ["privada-a", "privada-b"]) {
  assert.ok(aws.cidr.usableAddresses(sub(name).cidr) <= 2043, name + " es más grande de lo necesario");
}

const canonico = (cidr: string) => {
  const parsed = aws.cidr.parse(cidr);
  return parsed !== null && cidr === parsed.network + "/" + parsed.prefix;
};
assert.ok(canonico(plan.vpc), plan.vpc + " no está en forma canónica");
for (const { name, cidr } of plan.subnets) {
  assert.ok(canonico(cidr), name + " (" + cidr + ") no está en forma canónica");
}

