// Plan de la VPC 10.3.0.0/16: sin solape con las redes existentes y con las seis subredes en la mitad inferior.
export const plan = {
  vpc: "10.3.0.0/16",
  subnets: [
    { name: "publica-a", cidr: "10.3.0.0/26" },
    { name: "publica-b", cidr: "10.3.0.64/26" },
    { name: "publica-c", cidr: "10.3.0.128/26" },
    { name: "privada-a", cidr: "10.3.16.0/20" },
    { name: "privada-b", cidr: "10.3.32.0/20" },
    { name: "privada-c", cidr: "10.3.48.0/20" },
  ],
};

spec.code:
for (const existente of ["10.0.0.0/16", "10.1.0.0/16", "10.2.0.0/16"]) {
  assert.ok(!aws.cidr.overlaps(plan.vpc, existente), plan.vpc + " se solapa con " + existente);
}

const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["publica-a", "publica-b", "publica-c"]) {
  const hay = aws.cidr.usableAddresses(sub(name).cidr);
  assert.ok(hay >= 28, name + " ofrece " + hay + " direcciones utilizables y se piden 28");
}
for (const name of ["privada-a", "privada-b", "privada-c"]) {
  const hay = aws.cidr.usableAddresses(sub(name).cidr);
  assert.ok(hay >= 4000, name + " ofrece " + hay + " direcciones utilizables y se piden 4000");
}

const sub = (name: string) => {
  const found = plan.subnets.find((candidate: { name: string }) => candidate.name === name);
  assert.ok(found, "Falta la subred " + name);
  return found;
};
for (const name of ["publica-a", "publica-b", "publica-c"]) {
  assert.ok(aws.cidr.usableAddresses(sub(name).cidr) <= 59, name + " es más grande de lo necesario");
}
for (const name of ["privada-a", "privada-b", "privada-c"]) {
  assert.ok(aws.cidr.usableAddresses(sub(name).cidr) <= 4091, name + " es más grande de lo necesario");
}

const mitad = aws.cidr.split(plan.vpc, 17)[0];
assert.ok(mitad, "No se pudo calcular la mitad inferior de la VPC");
for (const { name, cidr } of plan.subnets) {
  assert.ok(aws.cidr.contains(mitad, cidr), name + " (" + cidr + ") queda fuera de la mitad inferior de la VPC " + mitad);
}

assert.deepStrictEqual(aws.cidr.validateVpcCidr(plan.vpc), []);
assert.strictEqual(aws.cidr.parse(plan.vpc)?.prefix, 16);
assert.ok(aws.cidr.contains("10.0.0.0/8", plan.vpc), plan.vpc + " no está dentro de 10.0.0.0/8");

const canonico = (cidr: string) => {
  const parsed = aws.cidr.parse(cidr);
  return parsed !== null && cidr === parsed.network + "/" + parsed.prefix;
};
assert.ok(canonico(plan.vpc), plan.vpc + " no está en forma canónica");
for (const { name, cidr } of plan.subnets) {
  assert.ok(canonico(cidr), name + " (" + cidr + ") no está en forma canónica");
}
